/*
 * Keep the header-only asio used by telemetry out of the dynamic symbol table.
 * Exported copies interpose on other libraries' asio, such as the Mooncake
 * Transfer Engine's libasio.so, which crashes when the asio versions differ.
 */
{
  local:
    extern "C++" {
      asio_*;
      *asio::*;
    };
};
